local function C_c()
local script = G2L["c"];
	-- Get services and player
	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	local Workspace = game:GetService("Workspace")
	local player = Players.LocalPlayer
	local mouse = player:GetMouse()

	-- GUI References
	local gui = script.Parent
	local mainFrame = gui:WaitForChild("MainFrame")
	local viewButton = mainFrame:WaitForChild("ViewCameras")

	-- Variables
	local cameras = {}
	local currentCameraIndex = 1
	local viewingMode = false
	local guiVisible = true

	-- Function to toggle GUI visibility
	local function toggleGUI()
		guiVisible = not guiVisible
		mainFrame.Visible = guiVisible
	end

	-- Detect Left Control key press to toggle GUI
	UserInputService.InputBegan:Connect(function(input, isProcessed)
		if not isProcessed and input.KeyCode == Enum.KeyCode.LeftControl then
			toggleGUI()
		end
	end)

	-- Create Camera
	mainFrame:WaitForChild("CreateCamera").MouseButton1Click:Connect(function()
		local tool = Instance.new("Tool")
		tool.Name = "CreateCamera"
		tool.RequiresHandle = false
		tool.Parent = player.Backpack

		tool.Activated:Connect(function()
			local camera = Instance.new("Part")
			camera.Anchored = true
			camera.Size = Vector3.new(2, 1, 2)
			camera.Position = mouse.Hit.p
			camera.Name = "Camera"
			camera.Parent = Workspace

			local decal = Instance.new("Decal")
			decal.Texture = "rbxassetid://8666406942"
			decal.Face = Enum.NormalId.Front
			decal.Parent = camera

			table.insert(cameras, camera)
		end)
	end)

	-- Rotate Camera
	mainFrame:WaitForChild("RotateCamera").MouseButton1Click:Connect(function()
		local tool = Instance.new("Tool")
		tool.Name = "RotateCamera"
		tool.RequiresHandle = false
		tool.Parent = player.Backpack

		local isDragging = false
		local selectedCamera = nil

		tool.Activated:Connect(function()
			if mouse.Target and mouse.Target.Name == "Camera" then
				selectedCamera = mouse.Target
				isDragging = true
			else
				isDragging = false
				selectedCamera = nil
			end
		end)

		UserInputService.InputChanged:Connect(function(input)
			if isDragging and selectedCamera and input.UserInputType == Enum.UserInputType.MouseMovement then
				local rotationAmount = CFrame.Angles(0, math.rad(input.Delta.X), 0)
				selectedCamera.CFrame = selectedCamera.CFrame * rotationAmount
			end
		end)

		tool.Unequipped:Connect(function()
			isDragging = false
			selectedCamera = nil
		end)
	end)

	-- Delete Camera
	mainFrame:WaitForChild("DeleteCamera").MouseButton1Click:Connect(function()
		local tool = Instance.new("Tool")
		tool.Name = "DeleteCamera"
		tool.RequiresHandle = false
		tool.Parent = player.Backpack

		tool.Activated:Connect(function()
			if mouse.Target and mouse.Target.Name == "Camera" then
				table.remove(cameras, table.find(cameras, mouse.Target))
				mouse.Target:Destroy()
			end
		end)
	end)

	-- Delete All Cameras
	mainFrame:WaitForChild("DeleteAllCameras").MouseButton1Click:Connect(function()
		for _, cam in ipairs(cameras) do
			cam:Destroy()
		end
		cameras = {}
	end)

	-- View Cameras
	viewButton.MouseButton1Click:Connect(function()
		viewingMode = not viewingMode

		if viewingMode and #cameras > 0 then
			Workspace.CurrentCamera.CameraType = Enum.CameraType.Scriptable
			Workspace.CurrentCamera.CFrame = cameras[currentCameraIndex].CFrame
		else
			Workspace.CurrentCamera.CameraType = Enum.CameraType.Custom
		end
	end)

	-- Camera Navigation using Left and Right Arrow Keys
	UserInputService.InputBegan:Connect(function(input, isProcessed)
		if not isProcessed and viewingMode and #cameras > 0 then
			if input.KeyCode == Enum.KeyCode.Right then
				currentCameraIndex = (currentCameraIndex % #cameras) + 1
				Workspace.CurrentCamera.CFrame = cameras[currentCameraIndex].CFrame
			elseif input.KeyCode == Enum.KeyCode.Left then
				currentCameraIndex = (currentCameraIndex - 2) % #cameras + 1
				Workspace.CurrentCamera.CFrame = cameras[currentCameraIndex].CFrame
			end
		end
	end)

end;
task.spawn(C_c);

